browser_evaluate {"function":"() => {
  const btns = document.querySelectorAll('button');
  return Array.from(btns).filter(b => b.getAttribute('aria-label') && b.getAttribute('aria-label').includes('next')).map(b => ({label: b.getAttribute('aria-label'), html: b.innerHTML.slice(0,200)}));
}"}

