browser_evaluate {"function":"() => {
  const btns = document.querySelectorAll('button[aria-label="next-button"]');
  const skinBtn = btns[btns.length-1];
  let count = 0;
  const doClick = () => {
    for (let i=0;i<30;i++){ skinBtn.click(); }
    count++;
  };
  doClick();
  return 'clicked many';
}"}

browser_evaluate {"function":"async () => {
  const btns = document.querySelectorAll('button[aria-label="next-button"]');
  const skinBtn = btns[btns.length-1];
  for (let i=0;i<20;i++){ skinBtn.click(); await new Promise(r=>setTimeout(r,250)); }
  return 'done';
}"}

